import Foundation

/// A 26-character Crockford base32 identifier: 48-bit timestamp + 80 bits of
/// randomness. Lexicographic order matches creation order, which is what makes
/// it usable as the final tie-break key in ranking (`Scoring.swift`).
///
/// IDs are generated by code, never by a model (see `docs/01-domain.md`).
public struct ULID: Hashable, Sendable, Comparable, CustomStringConvertible {
    /// Crockford base32: no I, L, O or U, so IDs cannot be misread aloud.
    static let alphabet = Array("0123456789ABCDEFGHJKMNPQRSTVWXYZ")
    static let length = 26

    public let rawValue: String

    /// Fails if the string is not 26 characters of valid Crockford base32.
    public init?(_ raw: String) {
        guard raw.count == Self.length else { return nil }
        let valid = Set(Self.alphabet)
        guard raw.allSatisfy({ valid.contains($0) }) else { return nil }
        self.rawValue = raw
    }

    /// Builds a ULID from an explicit timestamp and 10 bytes of entropy.
    /// Both are injected so tests can be fully deterministic.
    public init(timestampMilliseconds ms: UInt64, randomness: [UInt8]) {
        precondition(randomness.count == 10, "ULID randomness must be 10 bytes")
        var out = ""
        out.reserveCapacity(Self.length)

        // 48-bit timestamp over 10 characters (50 bits; top 2 are always zero).
        for i in 0..<10 {
            let shift = UInt64(5 * (9 - i))
            out.append(Self.alphabet[Int((ms >> shift) & 0x1F)])
        }
        // 80 bits of randomness over 16 characters — divides exactly, no padding.
        var buffer: UInt32 = 0
        var bits = 0
        for byte in randomness {
            buffer = (buffer << 8) | UInt32(byte)
            bits += 8
            while bits >= 5 {
                bits -= 5
                out.append(Self.alphabet[Int((buffer >> UInt32(bits)) & 0x1F)])
                buffer &= (1 << UInt32(bits)) - 1
            }
        }
        self.rawValue = out
    }

    /// Milliseconds since the Unix epoch, decoded from the first 10 characters.
    public var timestampMilliseconds: UInt64 {
        var value: UInt64 = 0
        for char in rawValue.prefix(10) {
            value = (value << 5) | UInt64(Self.alphabet.firstIndex(of: char) ?? 0)
        }
        return value
    }

    public var description: String { rawValue }
    public static func < (a: ULID, b: ULID) -> Bool { a.rawValue < b.rawValue }
}

/// Deterministic when seeded — every test that needs IDs gets reproducible ones.
public struct ULIDGenerator: Sendable {
    private let clock: @Sendable () -> UInt64
    private var rng: SplitMix64

    public init(
        seed: UInt64,
        clock: @escaping @Sendable () -> UInt64 = { UInt64(Date().timeIntervalSince1970 * 1000) }
    ) {
        self.rng = SplitMix64(seed: seed)
        self.clock = clock
    }

    public mutating func next() -> ULID {
        var bytes = [UInt8]()
        bytes.reserveCapacity(10)
        // 10 bytes = one 64-bit draw plus two more bytes from the next.
        let a = rng.next(), b = rng.next()
        for i in 0..<8 { bytes.append(UInt8((a >> (8 * UInt64(i))) & 0xFF)) }
        for i in 0..<2 { bytes.append(UInt8((b >> (8 * UInt64(i))) & 0xFF)) }
        return ULID(timestampMilliseconds: clock(), randomness: bytes)
    }
}

/// Small, fast, fully specified PRNG. Chosen over `SystemRandomNumberGenerator`
/// because property tests must be reproducible from their seed alone.
public struct SplitMix64: RandomNumberGenerator, Sendable {
    private var state: UInt64
    public init(seed: UInt64) { self.state = seed }

    public mutating func next() -> UInt64 {
        state &+= 0x9E37_79B9_7F4A_7C15
        var z = state
        z = (z ^ (z >> 30)) &* 0xBF58_476D_1CE4_E5B9
        z = (z ^ (z >> 27)) &* 0x94D0_49BB_1331_11EB
        return z ^ (z >> 31)
    }
}
